class BusyWorker implements Runnable {
    private volatile boolean running = true;
    public void run() {
        while (running) { /* aktywna praca, bez blokowania */ }
    }
    void shutdown() { running = false; }
}

class SleepyWorker implements Runnable {
    private volatile boolean running = true;
    public void run() {
        while (running) {
            try { Thread.sleep(5000); }
            catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                running = false;
            }
        }
    }
    void shutdown() { running = false; }
}

static void gracefulShutdown(SleepyWorker worker, Thread thread) throws InterruptedException {
    worker.shutdown();     // 1) flaga - worker sprawdzi ja po przebudzeniu
    thread.interrupt();    // 2) interrupt - budzi watek NATYCHMIAST z sleep()
    thread.join(2000);     // 3) czekamy na zakonczenie, zawsze z timeoutem
}

void shutdown() {
    running = false; // BLAD: watek w Thread.sleep(60000) zauwazy to dopiero za maks. 60s!
}

void shutdown(Thread workerThread) {
    running = false;
    workerThread.interrupt(); // budzi NATYCHMIAST, niezaleznie od pozostalego czasu sleep()
}

