class WaitingWorker implements Runnable {
    volatile boolean running = true;
    final Object lock = new Object();
    public void run() {
        synchronized (lock) {
            while (running) {
                try { lock.wait(5000); } catch (InterruptedException e) { Thread.currentThread().interrupt(); running=false; }
            }
        }
    }
    void shutdown() { running = false; }
}
