interface Stoppable { void stop() throws InterruptedException; }
static Stoppable startStoppableWorker(java.util.function.BooleanSupplier shouldContinue, Runnable iterationBody) {
    Thread t = new Thread(() -> { while (shouldContinue.getAsBoolean() && !Thread.currentThread().isInterrupted()) { iterationBody.run(); } });
    t.start();
    return () -> { t.interrupt(); t.join(2000); };
}
