class TwoPhaseWorker implements Runnable {
    volatile boolean stopRequested = false;
    public void run() {
        int zadanie = 0;
        while (!stopRequested) {
            zadanie++;
            System.out.println("wykonuje zadanie "+zadanie);
            try { Thread.sleep(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); System.out.println("przerwano NATYCHMIAST w trakcie zadania "+zadanie); return; }
        }
        System.out.println("graceful: zakonczono po "+zadanie+" zadaniach (bez przerywania w trakcie)");
    }
    void requestStop() { stopRequested = true; }
}
// scenariusz 1: tylko requestStop() - worker konczy AKTUALNE zadanie
// scenariusz 2: requestStop()+interrupt() - worker przerywa NATYCHMIAST

