interface Service { void start(); void stop() throws InterruptedException; boolean isRunning(); }
class ServiceManager {
    List<Service> serwisy = new ArrayList<>();
    void register(Service s) { serwisy.add(s); }
    void startAll() { for (Service s : serwisy) s.start(); }
    void stopAll() throws InterruptedException { for (Service s : serwisy) s.stop(); }
}
ServiceManager manager = new ServiceManager();
for (int i=0;i<5;i++) {
    boolean[] running = {false};
    Thread[] watekRef = new Thread[1];
    manager.register(new Service() {
        public void start() { running[0]=true; watekRef[0] = new Thread(() -> { while (running[0]) { try { Thread.sleep(100); } catch (InterruptedException e) { Thread.currentThread().interrupt(); running[0]=false; } } }); watekRef[0].start(); }
        public void stop() throws InterruptedException { running[0]=false; watekRef[0].interrupt(); watekRef[0].join(1000); }
        public boolean isRunning() { return running[0]; }
    });
}
manager.startAll();
Thread.sleep(50);
manager.stopAll();
System.out.println(manager.serwisy.stream().noneMatch(Service::isRunning));

