    boolean[] running = {true};
    int typ = rnd.nextInt(3);
    Runnable praca = switch (typ) {
        case 0 -> () -> { while (running[0]) Thread.onSpinWait(); };
        case 1 -> () -> { while (running[0]) { try { Thread.sleep(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); running[0]=false; } } };
        default -> () -> { Object lock = new Object(); synchronized (lock) { while (running[0]) { try { lock.wait(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); running[0]=false; } } } };
    };
    Thread t = new Thread(praca);
    t.start();
    watki.add(t);
    shutdowny.add(() -> running[0] = false);
}
