AtomicInteger zakonczoneCzysto = new AtomicInteger(0);
try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
    for (int i=0;i<1000;i++) {
        executor.submit(() -> {
            try {
                for (int krok=0; krok<10 && !Thread.currentThread().isInterrupted(); krok++) {
                    Thread.sleep(50);
                }
                zakonczoneCzysto.incrementAndGet();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                zakonczoneCzysto.incrementAndGet(); // rowniez liczymy jako 'czysto zakonczone' - poprawnie zareagowalo na przerwanie
            }
        });
    }
    // close() (niejawne, na koncu try-with-resources) czeka na zakonczenie WSZYSTKICH zadan
}
System.out.println("zakonczonych czysto: "+zakonczoneCzysto.get()+"/1000");
